public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        // maxRows validation
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200 inclusive');
        }

        // Object validation
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required');
        }

        Schema.SObjectType objType = resolveSObjectType(objectApiName);
        if (objType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDesc = objType.getDescribe();
        if (!objDesc.isQueryable()) {
            throw new SearchException('User does not have read access to object: ' + objectApiName);
        }

        // Fields validation
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list is required');
        }

        Map<String, Schema.DescribeFieldResult> fieldDescMap = buildFieldDescMap(objDesc);

        Set<String> selectFieldNames = new Set<String>();
        selectFieldNames.add('Id');

        for (String fieldName : fields) {
            if (fieldName == null || String.isBlank(fieldName)) {
                throw new SearchException('Field name cannot be blank');
            }
            Schema.DescribeFieldResult d = getFieldDescribe(fieldDescMap, fieldName);
            if (d == null) {
                throw new SearchException('Field does not exist: ' + fieldName);
            }
            if (!d.isAccessible()) {
                throw new SearchException('Field is not readable: ' + fieldName);
            }
            selectFieldNames.add(d.getName());
        }

        // Filter keys validation
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (filterKey == null || String.isBlank(filterKey)) {
                    throw new SearchException('Filter key cannot be blank');
                }
                Schema.DescribeFieldResult d = getFieldDescribe(fieldDescMap, filterKey);
                if (d == null) {
                    throw new SearchException('Filter field does not exist: ' + filterKey);
                }
                if (!d.isAccessible()) {
                    throw new SearchException('Filter field is not readable: ' + filterKey);
                }
                if (!d.isFilterable()) {
                    throw new SearchException('Filter field is not filterable: ' + filterKey);
                }
            }
        }

        // Order-by validation
        String orderFieldApi = null;
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult d = getFieldDescribe(fieldDescMap, orderByField);
            if (d == null) {
                throw new SearchException('Order field does not exist: ' + orderByField);
            }
            if (!d.isAccessible()) {
                throw new SearchException('Order field is not readable: ' + orderByField);
            }
            if (!d.isSortable()) {
                throw new SearchException('Order field is not sortable: ' + orderByField);
            }
            orderFieldApi = d.getName();
        }

        // Build SOQL
        String objectApiCorrect = objDesc.getName();
        List<String> selectFields = new List<String>(selectFieldNames);
        String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objectApiCorrect;

        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                Schema.DescribeFieldResult d = getFieldDescribe(fieldDescMap, filterKey);
                String apiName = d.getName();
                Object value = filters.get(filterKey);
                conditions.add(apiName + ' = ' + formatValue(value));
            }
        }

        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderFieldApi)) {
            soql += ' ORDER BY ' + orderFieldApi + ' ASC';
        }

        soql += ' LIMIT ' + maxRows;

        try {
            return Database.query(soql);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Search execution failed: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType resolveSObjectType(String apiName) {
        Map<String, Schema.SObjectType> gd = Schema.getGlobalDescribe();
        Schema.SObjectType result = gd.get(apiName);
        if (result != null) {
            return result;
        }
        String lower = apiName.toLowerCase();
        for (String key : gd.keySet()) {
            if (key != null && key.toLowerCase() == lower) {
                return gd.get(key);
            }
        }
        return null;
    }

    private static Map<String, Schema.DescribeFieldResult> buildFieldDescMap(Schema.DescribeSObjectResult objDesc) {
        Map<String, Schema.DescribeFieldResult> map = new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField fieldToken : objDesc.fields.getMap().values()) {
            Schema.DescribeFieldResult d = fieldToken.getDescribe();
            if (d != null) {
                map.put(d.getName().toLowerCase(), d);
            }
        }
        return map;
    }

    private static Schema.DescribeFieldResult getFieldDescribe(Map<String, Schema.DescribeFieldResult> map, String fieldName) {
        if (map == null || String.isBlank(fieldName)) {
            return null;
        }
        return map.get(fieldName.toLowerCase());
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof String || value instanceof Id) {
            return "'" + String.escapeSingleQuotes(String.valueOf(value)) + "'";
        }
        return String.valueOf(value);
    }
}
