public with sharing class ContactLookupAction {

    @InvocableMethod(
        label = 'Find Contact by Email'
        description = 'Finds an existing contact by email address.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect trimmed emails and unique lookup keys for a single query
        List<String> trimmedEmails = new List<String>();
        Set<String> uniqueKeys = new Set<String>();

        for (Request req : requests) {
            String raw = (req != null && req.email != null) ? req.email.trim() : '';
            trimmedEmails.add(raw);
            if (String.isNotBlank(raw)) {
                uniqueKeys.add(raw.toLowerCase());
            }
        }

        // One SOQL query for all unique emails; earliest CreatedDate wins
        Map<String, Contact> earliestByKey = new Map<String, Contact>();
        if (!uniqueKeys.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueKeys
                ORDER BY CreatedDate ASC
            ]) {
                String key = (c.Email != null) ? c.Email.trim().toLowerCase() : null;
                if (String.isNotBlank(key) && !earliestByKey.containsKey(key)) {
                    earliestByKey.put(key, c);
                }
            }
        }

        // Build exactly one Result per Request, preserving input order
        for (Integer i = 0; i < requests.size(); i++) {
            String email = trimmedEmails[i];
            Result res = new Result();

            if (String.isNotBlank(email)) {
                Contact match = earliestByKey.get(email.toLowerCase());
                if (match != null) {
                    res.found = true;
                    res.contactId = match.Id;
                } else {
                    res.found = false;
                    res.contactId = null;
                }
            } else {
                res.found = false;
                res.contactId = null;
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(
            label = 'Email'
            description = 'The email address to search for.'
            required = true
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label = 'Contact ID'
            description = 'The ID of the found contact.'
        )
        public Id contactId;

        @InvocableVariable(
            label = 'Found'
            description = 'True if a matching contact was found.'
        )
        public Boolean found;
    }
}
