public with sharing class OpportunityPipelineHandler {
    public static void handle(List<Opportunity> newOpportunities, List<Opportunity> oldOpportunities, System.TriggerOperation operation) {
        Set<Id> accountIds = new Set<Id>();

        if (operation == System.TriggerOperation.DELETE) {
            for (Opportunity o : oldOpportunities) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (operation == System.TriggerOperation.INSERT || operation == System.TriggerOperation.UNDELETE) {
            for (Opportunity o : newOpportunities) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (operation == System.TriggerOperation.UPDATE) {
            for (Integer i = 0; i < newOpportunities.size(); i++) {
                Opportunity newO = newOpportunities[i];
                Opportunity oldO = oldOpportunities[i];

                Boolean relevant = false;
                if (newO.AccountId != oldO.AccountId) {
                    relevant = true;
                }
                if (newO.IsClosed != oldO.IsClosed) {
                    relevant = true;
                }
                if (newO.Amount != oldO.Amount) {
                    relevant = true;
                }

                if (relevant) {
                    if (oldO.AccountId != null) {
                        accountIds.add(oldO.AccountId);
                    }
                    if (newO.AccountId != null) {
                        accountIds.add(newO.AccountId);
                    }
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, AggregateResult> aggByAccount = new Map<Id, AggregateResult>();
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            aggByAccount.put((Id) ar.get('AccountId'), ar);
        }

        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accId : accountIds) {
            Account acc = currentAccounts.get(accId);
            if (acc == null) {
                continue;
            }

            Decimal pipeline = 0;
            Decimal count = 0;

            if (aggByAccount.containsKey(accId)) {
                AggregateResult ar = aggByAccount.get(accId);
                Decimal sumAmount = (Decimal) ar.get('total');
                pipeline = (sumAmount != null) ? sumAmount : 0;
                count = (Decimal) ar.get('cnt');
            }

            Decimal existingPipeline = (acc.FB_Open_Pipeline__c != null) ? acc.FB_Open_Pipeline__c : 0;
            Decimal existingCount = (acc.FB_Open_Opportunities__c != null) ? acc.FB_Open_Opportunities__c : 0;

            if (existingPipeline.compareTo(pipeline) != 0 || existingCount.compareTo(count) != 0) {
                accountsToUpdate.add(new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = pipeline,
                    FB_Open_Opportunities__c = count
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
