public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Every requested account maps to 0 initially
        for (Id accId : accountIds) {
            result.put(accId, Decimal.valueOf(0));
        }

        Integer currentYear = Date.today().year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date endOfYear = Date.newInstance(currentYear, 12, 31);

        // Single aggregate query; no individual records loaded
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND CloseDate >= :startOfYear
              AND CloseDate <= :endOfYear
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal sum = (Decimal) ar.get('total');
            result.put(accountId, (sum == null) ? Decimal.valueOf(0) : sum);
        }

        return result;
    }
}
