public class ContactPhoneCleanup {
    /**
     * Normalizes Phone values for the given Contact Ids.
     * Changes made to your approach:
     *  - Added null/empty guard on the incoming list and on each Phone.
     *  - Only contacts with a non-blank Phone are included in the update list.
     *  - Uses replaceAll for bulk-safe character stripping.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errors;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            // Leave contacts without a phone out
            if (String.isNotBlank(c.Phone)) {
                // Remove every character that is not a digit or '+'
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(c);
            }
        }

        // Single bulk update with all-or-none = false
        if (!contactsToUpdate.isEmpty()) {
            Database.SaveResult[] results = Database.update(contactsToUpdate, false);

            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    Id failedId = contactsToUpdate[i].Id;
                    String firstMessage = results[i].getErrors()[0].getMessage();
                    errors.put(failedId, firstMessage);
                }
            }
        }

        return errors;
    }
}
