public with sharing class StaleOpportunityCloser {
    /**
     * Closes open Opportunities whose CloseDate is strictly before the
     * cutoff by setting StageName to 'Closed Lost'.
     *
     * Uses a list-form SOQL for loop so only 200 records are held in memory
     * at once. Updates each chunk immediately.
     *
     * CHANGES I WOULD MAKE:
     * 1. If volume can exceed 10,000 DML rows or 50,000 query rows, move to
     *    Batchable (or Queueable chain) because a synchronous Schedulable
     *    is capped by synchronous governor limits.
     * 2. Use Database.update(chunk, false) and count successes instead of
     *    a hard update so one bad record doesn't roll back the whole chunk.
     * 3. Add a try/catch around the update and log errors via a custom object
     *    or platform event for auditability.
     * 4. Add WITH SECURITY_ENFORCED or explicit field-level checks if this
     *    is ever called by a non-admin user (here it is admin-only via
     *    scheduled job, but defense in depth is best practice).
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer closedCount = 0;

        // List-form SOQL for loop: Salesforce automatically chunks at 200.
        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
