public with sharing class AccountRatingService {

    @future
    public static void recalculate(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Default to Cold; aggregate updates to Hot or Warm
        Map<Id, String> ratingByAccount = new Map<Id, String>();
        for (Id accId : accountIds) {
            ratingByAccount.put(accId, 'Cold');
        }

        for (AggregateResult ar : [
            SELECT AccountId, MAX(Amount) maxAmt, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal maxAmt = (Decimal) ar.get('maxAmt');
            Integer oppCount = (Integer) ar.get('oppCount');

            if (maxAmt != null && maxAmt >= 100000) {
                ratingByAccount.put(accId, 'Hot');
            } else if (oppCount != null && oppCount > 0) {
                ratingByAccount.put(accId, 'Warm');
            } else {
                ratingByAccount.put(accId, 'Cold');
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : ratingByAccount.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accId,
                Rating = ratingByAccount.get(accId)
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
