trigger CaseTrigger on Case (after update) {
    /*
     * After update: detects cases that just changed from open to closed,
     * have a Contact, and enqueues one isolated Queueable per case.
     * 
     * Changes made for production / bulk safety:
     * - Uses Trigger.oldMap to verify IsClosed transition.
     * - Filters out cases without ContactId.
     * - Guards enqueue count with Limits.getQueueableJobs() because
     *   Salesforce allows max 50 Queueable jobs per synchronous transaction.
     *   This prevents LimitException when agents bulk-close cases or
     *   the nightly API cleanup closes up to 200 at once.
     */
    List<Id> newlyClosedWithContact = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (oldCase != null && !oldCase.IsClosed && c.IsClosed && c.ContactId != null) {
            newlyClosedWithContact.add(c.Id);
        }
    }

    Integer maxEnqueue = Math.max(0, 50 - Limits.getQueueableJobs());

    for (Integer i = 0; i < Math.min(newlyClosedWithContact.size(), maxEnqueue); i++) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedWithContact[i]));
    }

    if (newlyClosedWithContact.size() > maxEnqueue) {
        System.debug(LoggingLevel.WARN, 'Queueable enqueue limit reached; ' +
            (newlyClosedWithContact.size() - maxEnqueue) +
            ' case(s) not enqueued. For bulk >50 use a dispatcher or bulk Queueable.');
    }
}
