public with sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    /*
     * Queueable that creates the CSAT survey Task for a single Case.
     * 
     * Changes made for production / best practice:
     * - with sharing enforces record access rules.
     * - Database.AllowsCallouts prepares for future vendor integration.
     * - Queries current Case data in execute (not relying solely on trigger state).
     * - Uses WITH SECURITY_ENFORCED for FLS/CRUD safety.
     * - Try/catch isolates failure to this job so one bad case doesn't affect others.
     * - Only creates Task when case is still closed and has a contact.
     */
    private Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        try {
            Case c = [
                SELECT Id, CaseNumber, ContactId, IsClosed
                FROM Case
                WHERE Id = :caseId
                WITH SECURITY_ENFORCED
                LIMIT 1
            ];

            if (c == null || c.ContactId == null || !c.IsClosed) {
                return;
            }

            Task surveyTask = new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            );

            insert surveyTask;
        } catch (Exception ex) {
            System.debug(LoggingLevel.ERROR, 'CaseSurveyJob failed for caseId=' + caseId +
                ': ' + ex.getMessage());
            // Production enhancement: log to a custom error object or notify via Platform Event.
        }
    }
}
