     * 1. Messaging.sendEmail can be invoked only 10 times per Apex transaction.
     *    Calling it once per opportunity for up to 200 records exceeds that
     *    limit and will throw a LimitException. Production code should batch
     *    messages (max 100 per call) and call sendEmail once or twice.
     * 2. Opportunity owners may be Queues (key prefix 00G), not Users (005).
     *    setTargetObjectId requires a User/Contact/Lead, so Queue owners
     *    cause errors. Filter to User owners or fall back to setToAddresses.
     * 3. Without try/catch, a single invalid target/exception aborts the loop.
     *    The try/catch below isolates failures so remaining emails go out.
     * 4. Looping is inefficient; prefer bulk collecting messages and sending
     *    in batches.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentCount = 0;
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk-safe query; handles up to 200 records.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        for (Opportunity opp : opportunities) {
            // Only Users are valid for setTargetObjectId.
            // Queues (00G) and other owners must be skipped or handled differently.
            if (opp.OwnerId == null || !String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String body = 'Renewal due for opportunity ' + opp.Name + '.';
            if (opp.CloseDate != null) {
                body += ' Close date: ' + opp.CloseDate.format();
            }
            mail.setPlainTextBody(body);

            // One invocation per opportunity as requested.
            // Wrapped so a failure on one does not stop the others.
            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(
                    new Messaging.SingleEmailMessage[] { mail }
                );
                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception ex) {
                System.debug(LoggingLevel.ERROR, 'Renewal reminder failed for opp ' + opp.Id + ': ' + ex.getMessage());
            }
        }

        return sentCount;
    }
}
