import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD, REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    @api recordId;

    account;
    error;
    loading = true;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ error, data }) {
        if (data) {
            this.account = data;
            this.error = undefined;
            this.loading = false;
        } else if (error) {
            this.error = error;
            this.account = undefined;
            this.loading = false;
        } else {
            // Parameter changed or initial load: show spinner, clear prior data
            this.loading = true;
            this.account = undefined;
            this.error = undefined;
        }
    }

    get errorMessage() {
        return this.error?.body?.message;
    }

    get name() {
        return this.account?.fields?.Name?.value;
    }

    get industry() {
        return this.account?.fields?.Industry?.value;
    }

    get revenue() {
        return this.account?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        if (!this.account || !this.account.fields) {
            return undefined;
        }
        const fields = this.account.fields;
        if (fields.Owner) {
            return fields.Owner.displayValue || fields.Owner.value;
        }
        if (fields['Owner.Name']) {
            return fields['Owner.Name'].value || fields['Owner.Name'].displayValue;
        }
        return undefined;
    }
}
