    }

    generateCaseUrl() {
        const pageRef = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.GenerateUrl](pageRef)
            .then(url => {
                this.caseUrl = url;
            })
            .catch(error => {
                console.error('Error generating case URL', error);
            });
    }

    handleClick(event) {
        const action = event.target.dataset.action;
        let pageRef;

        switch (action) {
            case 'new-contact':
                pageRef = {
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                };
                break;
            case 'contacts':
                pageRef = {
                    type: 'standard__recordRelationshipPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        relationshipApiName: 'Contacts',
                        actionName: 'view'
                    }
                };
                break;
            case 'edit':
                pageRef = {
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        actionName: 'edit'
                    }
                };
                break;
            default:
                return;
        }

        if (pageRef) {
            this[NavigationMixin.Navigate](pageRef);
        }
    }
}
