import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting = 0;
    longestWaitMinutes = 0;
    isLoaded = false;
    isLoading = false;
    error = null;
    timerId = null;

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this.loadStats();
        }
    };

    get errorMessage() {
        return this.error?.body?.message || '';
    }

    connectedCallback() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);

        if (document.visibilityState === 'visible') {
            this.loadStats();
        }

        this.startTimer();
    }

    disconnectedCallback() {
        this.stopTimer();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    startTimer() {
        if (this.timerId) {
            return;
        }
        this.timerId = setInterval(() => {
            if (document.visibilityState === 'hidden') {
                return;
            }
            if (this.isLoading) {
                return;
            }
            this.loadStats();
        }, 60000);
    }

    stopTimer() {
        if (this.timerId) {
            clearInterval(this.timerId);
            this.timerId = null;
        }
    }

    async loadStats() {
        if (this.isLoading) {
            return;
        }
        this.isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting ?? 0;
            this.longestWaitMinutes = result.longestWaitMinutes ?? 0;
            this.isLoaded = true;
            this.error = null;
        } catch (err) {
            this.error = err;
        } finally {
            this.isLoading = false;
        }
    }
}
