    handleChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    async handleRegister() {
        // 1. Work-email check and custom validity
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            const emailValue = emailInput.value || '';
            const domain = (emailValue.split('@').pop() || '').toLowerCase();
            const blocked = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
            if (blocked.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // 2. Report validity on all inputs at once
        const inputs = this.template.querySelectorAll('lightning-input');
        inputs.forEach(input => input.reportValidity());

        // 3. Stop if any invalid; otherwise call Apex
        const allValid = Array.from(inputs).every(input => input.checkValidity());
        if (!allValid) {
            return;
        }

        const fullNameInput = this.template.querySelector('lightning-input[data-field="fullName"]');
        const emailInputForRegister = this.template.querySelector('lightning-input[data-field="email"]');
        const companyInput = this.template.querySelector('lightning-input[data-field="company"]');

        try {
            await register({
                fullName: fullNameInput ? fullNameInput.value : this.fullName,
                email: emailInputForRegister ? emailInputForRegister.value : this.email,
                company: companyInput ? companyInput.value : this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
