import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        const newVal = val === undefined || val === null ? '' : val;
        if (newVal !== this._value) {
            this._value = newVal;
            this.syncActiveIndex();
        }
    }

    syncActiveIndex() {
        const opts = this._options;
        if (!opts || opts.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const idx = opts.findIndex(o => o.value === this._value);
        if (idx >= 0) {
            this._activeIndex = idx;
        } else {
            this._activeIndex = 0;
        }
    }

    get processedOptions() {
        const opts = this.options || [];
        return opts.map((opt, idx) => ({
            ...opt,
            id: `status-option-${idx}`,
            selectedStr: this._value === opt.value ? 'true' : 'false',
            index: idx
        }));
    }

    get activeDescendantId() {
        const opts = this.options || [];
        if (opts.length === 0 || this._activeIndex < 0 || this._activeIndex >= opts.length) {
            return undefined;
        }
        return `status-option-${this._activeIndex}`;
    }

    handleKeyDown(event) {
        const handled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        const key = event.key;
        if (!handled.includes(key)) {
            return;
        }
        event.preventDefault();

        const opts = this.options || [];
        if (opts.length === 0) {
            return;
        }

        if (key === 'ArrowDown') {
            if (this._activeIndex < opts.length - 1) {
                this._activeIndex++;
            }
        } else if (key === 'ArrowUp') {
            if (this._activeIndex > 0) {
                this._activeIndex--;
            }
        } else if (key === 'Home') {
            this._activeIndex = 0;
        } else if (key === 'End') {
            this._activeIndex = opts.length - 1;
        } else if (key === 'Enter' || key === ' ') {
            const idx = this._activeIndex;
            if (idx >= 0 && idx < opts.length) {
                const val = opts[idx].value;
                if (this._value !== val) {
                    this.value = val;
                    this.dispatchChange(val);
                }
            }
        }
    }

    handleOptionClick(event) {
        const idx = parseInt(event.currentTarget.dataset.index, 10);
        if (isNaN(idx)) {
            return;
        }
        const opts = this.options || [];
        if (idx < 0 || idx >= opts.length) {
            return;
        }

        this._activeIndex = idx;
        const val = opts[idx].value;
        if (this._value !== val) {
            this.value = val;
            this.dispatchChange(val);
        }
    }

    dispatchChange(value) {
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
}
