        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const id = `new-${Date.now()}-${this.nextId++}`;
        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', {
            detail: { label },
            bubbles: true,
            composed: true
        }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map(task => {
            if (task.id === id) {
                return { ...task, done: !task.done };
            }
            return task;
        });
    }
