public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();
        List<npe5__Affiliation__c> newAffiliations = new List<npe5__Affiliation__c>();

        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            Id targetOrgId = employerByContactId.get(c.Id);
            if (targetOrgId == null) {
                continue;
            }

            // Already primary — nothing changes, avoid duplicate affiliation.
            if (c.npsp__Primary_Affiliation__c == targetOrgId) {
                continue;
            }

            newAffiliations.add(new npe5__Affiliation__c(
                npe5__Contact__c = c.Id,
                npe5__Organization__c = targetOrgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            ));
        }

        if (!newAffiliations.isEmpty()) {
            insert newAffiliations;
        }
    }
}
