public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // Validate map is present and not empty
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent by GAU map is null or empty');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Decimal totalPercent = 0;

        // Validate each percentage
        for (Id gauId : gauIds) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage must be greater than 0');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Percentages add up to more than 100');
        }

        // Validate GAUs exist and are active
        List<npsp__General_Accounting_Unit__c> gauRecords = [
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ];
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(gauRecords);

        for (Id gauId : gauIds) {
            if (!gauMap.containsKey(gauId)) {
                throw new AllocationException('GAU is inactive or does not exist');
            }
            if (gauMap.get(gauId).npsp__Active__c != true) {
                throw new AllocationException('GAU is inactive');
            }
        }

        // Fetch opportunity amount (needed to set correct amounts at insert time)
        List<Opportunity> oppList = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (oppList.isEmpty()) {
            throw new AllocationException('Opportunity not found');
        }
        Decimal opportunityAmount = oppList[0].Amount;

        // All validation complete — now modify data
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            Decimal pct = percentByGauId.get(gauId);
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = pct;
            // Set amount based on current opportunity amount so the record is correct now;
            // the Percent field ensures it stays correct when the opportunity amount changes.
            alloc.npsp__Amount__c = (opportunityAmount != null) ? opportunityAmount * pct / 100 : null;
            newAllocations.add(alloc);
        }

        insert newAllocations;
        return newAllocations;
    }
}
