public class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // Validation
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanService().new PaymentPlanException(
                'Number of payments must be at least 1.'
            );
        }

        List<Opportunity> opps = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opps.isEmpty()) {
            throw new PaymentPlanService().new PaymentPlanException(
                'Opportunity not found.'
            );
        }

        Opportunity opp = opps[0];
        if (opp.IsClosed) {
            throw new PaymentPlanService().new PaymentPlanException(
                'Opportunity is closed.'
            );
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal outstanding = (opp.Amount == null) ? Decimal.ZERO : opp.Amount;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : existingPayments) {
            Boolean isPaid = p.npe01__Paid__c == true;
            Boolean isWrittenOff = p.npe01__Written_Off__c == true;

            if (isPaid || isWrittenOff) {
                Decimal amt = (p.npe01__Payment_Amount__c == null)
                    ? Decimal.ZERO
                    : p.npe01__Payment_Amount__c;
                outstanding -= amt;
            } else {
                paymentsToDelete.add(p);
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanService().new PaymentPlanException(
                'Outstanding amount must be greater than zero.'
            );
        }

        Decimal divisor = Decimal.valueOf(numberOfPayments);
        Decimal baseAmount = outstanding.divide(divisor, 2, System.RoundingMode.DOWN);

        Decimal allocated = Decimal.ZERO;
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amt;
            if (i == numberOfPayments - 1) {
                amt = outstanding - allocated;
            } else {
                amt = baseAmount;
            }

            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c = opportunityId;
            payment.npe01__Payment_Amount__c = amt;
            payment.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            payment.npe01__Paid__c = false;
            payment.npe01__Written_Off__c = false;

            newPayments.add(payment);
            allocated += amt;
        }

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        if (!newPayments.isEmpty()) {
            insert newPayments;
        }

        return newPayments;
    }
}
