public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // If the user cannot read the object at all, return empty list.
        if (!Schema.SObjectType.FB_Employee__c.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Static SOQL respects sharing (with sharing) and selects all fields.
        List<FB_Employee__c> employees = [
            SELECT Id, Name, Department__c, Salary__c, Personal_Email__c
            FROM FB_Employee__c
            ORDER BY Name ASC
        ];

        // Remove fields the running user does not have read access to.
        // enforceCRUD is false because object-level access was already verified.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            employees,
            false
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
