public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        TriggerBase.bypass('Account');
        try {
            List<Account> accounts = [SELECT Id FROM Account WHERE Id IN :accountIds];
            for (Account acc : accounts) {
                acc.OwnerId = newOwnerId;
            }

            List<Contact> contacts = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];
            for (Contact con : contacts) {
                con.OwnerId = newOwnerId;
            }

            if (!accounts.isEmpty()) {
                update accounts;
            }
            if (!contacts.isEmpty()) {
                update contacts;
            }
        } finally {
            TriggerBase.clearBypass('Account');
        }
    }
}
