public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    public void beforeInsert(List<SObject> triggerNew) {
        enforce(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce(triggerNew, triggerOld);
    }

    private void enforce(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        Set<String> emailSet = new Set<String>();
        Set<Id> updateIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew[i];
            Boolean shouldCheck = false;
            if (triggerOld == null) {
                shouldCheck = c.AccountId != null && String.isNotBlank(c.Email);
            } else {
                Contact old = (Contact) triggerOld[i];
                shouldCheck = (c.AccountId != null && String.isNotBlank(c.Email))
                    && (c.Email != old.Email || c.AccountId != old.AccountId);
            }

            if (shouldCheck) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
                if (String.isNotBlank(c.Email)) {
                    emailSet.add(c.Email.toLowerCase());
                }
                if (c.Id != null) {
                    updateIds.add(c.Id);
                }
            }
        }

        Set<String> existingKeys = new Set<String>();
        if (!accountIds.isEmpty() && !emailSet.isEmpty()) {
            for (Contact ec : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emailSet
                  AND Id NOT IN :updateIds
            ]) {
                if (ec.AccountId != null && String.isNotBlank(ec.Email)) {
                    existingKeys.add(ec.AccountId + '|' + ec.Email.toLowerCase());
                }
            }
        }

        Set<String> seenKeys = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew[i];
            Boolean shouldCheck = false;
            if (triggerOld == null) {
                shouldCheck = c.AccountId != null && String.isNotBlank(c.Email);
            } else {
                Contact old = (Contact) triggerOld[i];
                shouldCheck = (c.AccountId != null && String.isNotBlank(c.Email))
                    && (c.Email != old.Email || c.AccountId != old.AccountId);
            }

            if (!shouldCheck) {
                continue;
            }

            String key = c.AccountId + '|' + c.Email.toLowerCase();
            Boolean intraListError = seenKeys.contains(key);
            if (!intraListError) {
                seenKeys.add(key);
            }

            Boolean dbConflict = existingKeys.contains(key);

            if (intraListError || dbConflict) {
                c.addError('Another contact on this account already uses this email address.');
            }
        }
    }
}
